      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">APPLY THIS WEEK</text><text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">Three actions to start now</text><rect x=\"150\" y=\"200\" width=\"800\" height=\"180\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"200\" y=\"265\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"28\">1.</text><text x=\"260\" y=\"265\" fill=\"#fff\" font-size=\"24\">Subscribe to one growth newsletter</text><text x=\"260\" y=\"310\" fill=\"#888\" font-size=\"20\">Reforge, GrowthHackers, Lenny's</text><text x=\"260\" y=\"345\" fill=\"#888\" font-size=\"20\">5 nights, one essay each</text><rect x=\"150\" y=\"410\" width=\"800\" height=\"180\" rx=\"20\" fill=\"rgba(139,92,246,0.12)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/><text x=\"200\" y=\"475\" fill=\"#8b5cf6\" font-weight=\"bold\" font-size=\"28\">2.</text><text x=\"260\" y=\"475\" fill=\"#fff\" font-size=\"24\">Reverse-engineer one product</text><text x=\"260\" y=\"520\" fill=\"#888\" font-size=\"20\">Sign up, map the funnel,</text><text x=\"260\" y=\"555\" fill=\"#888\" font-size=\"20\">document day 1 to day 7</text><rect x=\"150\" y=\"620\" width=\"800\" height=\"180\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"200\" y=\"685\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"28\">3.</text><text x=\"260\" y=\"685\" fill=\"#fff\" font-size=\"24\">Install Mixpanel or PostHog</text><text x=\"260\" y=\"730\" fill=\"#888\" font-size=\"20\">On a side project</text><text x=\"260\" y=\"765\" fill=\"#888\" font-size=\"20\">Instrument one funnel</text></svg>",
