      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">KNOWLEDGE CHECK</text><text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">Diagnose the gap</text><rect x=\"80\" y=\"200\" width=\"940\" height=\"280\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"265\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"26\">The Pattern</text><text x=\"550\" y=\"330\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Day 7: 95% retention</text><text x=\"550\" y=\"375\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Day 90: 25% retention</text><text x=\"550\" y=\"430\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">70-point cliff between activation and habit.</text><rect x=\"80\" y=\"510\" width=\"940\" height=\"340\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"550\" y=\"570\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"26\">Diagnosis: Long-Term Gap</text><text x=\"130\" y=\"635\" fill=\"#fff\" font-size=\"22\">Activation is excellent</text><text x=\"130\" y=\"680\" fill=\"#fff\" font-size=\"22\">Habit formation is weak</text><text x=\"130\" y=\"725\" fill=\"#fff\" font-size=\"22\">Product not becoming irreplaceable</text><text x=\"550\" y=\"790\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Fix: Hook loop, power features, integrations.</text></svg>",
